export const SAMPLE_STATS = {
  totalSwatches: SWATCHES.length,
  totalCategories: SWATCH_CATEGORIES.length,
  headline: '430+ Pom Pom Swatches',
} as const

const CATEGORY_MAP = Object.fromEntries(
  SWATCH_CATEGORIES.map((c) => [c.id, c]),
) as Record<SwatchCategoryId, SwatchCategory>

export function getCategory(id: SwatchCategoryId): SwatchCategory {
  return CATEGORY_MAP[id]
}

export function filterSwatches(filter: SwatchFilterId): Swatch[] {
  if (filter === 'all') return SWATCHES
  return SWATCHES.filter((s) => s.categoryId === filter)
}

export function swatchesForCategory(id: SwatchCategoryId): Swatch[] {
  return SWATCHES.filter((s) => s.categoryId === id)
}

export function categoriesToShow(filter: SwatchFilterId): SwatchCategory[] {
  if (filter === 'all') return SWATCH_CATEGORIES
  return SWATCH_CATEGORIES.filter((c) => c.id === filter)
}